    muted_glade: { name: 'The Meadow of Muted Birds', kind: 'grove', at: [300, 228], size: 7, desc: 'A vibrant glade full of fruiting trees and dozens of small birds, utterly silent.' },
    tone_statue: { name: 'The Guardian of the Forgotten Tone', kind: 'stone', at: [398, 300], size: 5, height: 3, desc: 'A great stone figure of a seated druid, its face broken, a dried flower and a dissonant crystal in its chest.' },
    withered_grove: { name: 'The Withered Grove', kind: 'grove', at: [700, 380], size: 7, blocks: { leaves: 'air', log: 'stripped_dark_oak_log' }, desc: 'A stretch of woodland, barren now, black sap beading on the bark.' },
    mourning_stone: { name: 'The Mourning Stone', kind: 'stone', at: [820, 420], size: 5, height: 5, desc: 'A great upright stone carved with spirals and a woman\'s name, eroded by time. Flowers never grow here.' },
    swarm_ridge: { name: 'The Songbird Ridge', kind: 'camp', at: [780, 452], size: 6, boss: 'swarmbeak_matriarch', minions: [['swarmbeak', 3]], wake: 16, bossIf: { quest: 'q8', active: true }, desc: 'Black-plumed birds circle here, repeating a tune from the Vale, warped.' },
