    sending_crystal: { name: 'Sending Crystal', art: 'orb', cols: ['#7ab0ff', '#2a3a8a', '#e8d8ff'], recall: true, quest: true, desc: 'A palm-sized crystal from Eldon, its runes slowly turning. Use it to call yourself home to any Resonance Anchor you are attuned to (once until your next long rest).' },
